-- generated by tools/build.py - the peak list for the leaderboard. Run in the Supabase SQL Editor after 02 (and again when peaks change).
-- lat / lon: for the GPS summit check of the app (07_verify.sql)
alter table public.peaks add column if not exists lat double precision, add column if not exists lon double precision;
on conflict (id) do update set name = excluded.name, elev = excluded.elev, tier = excluded.tier, prominent = excluded.prominent, lat = excluded.lat, lon = excluded.lon;
-- merged duplicate: ostrv-2104 -> kainradlturm-2103 (data/id_moves.json): climbs and routes move to the kept peak
update public.ascents k set deleted = false, climbed_on = coalesce(k.climbed_on, o.climbed_on), route_name = coalesce(k.route_name, o.route_name), note = coalesce(k.note, o.note)
  from public.ascents o where o.user_id = k.user_id and o.peak_id = 'ostrv-2104' and not o.deleted and k.peak_id = 'kainradlturm-2103';
update public.ascents a set peak_id = 'kainradlturm-2103' where peak_id = 'ostrv-2104' and not exists (select 1 from public.ascents b where b.user_id = a.user_id and b.peak_id = 'kainradlturm-2103');
delete from public.ascents where peak_id = 'ostrv-2104';
update public.routes set peak_ids = array_replace(peak_ids, 'ostrv-2104', 'kainradlturm-2103') where 'ostrv-2104' = any(peak_ids);
